begin;
create function "authorization".active_class(target_school uuid,target_class uuid) returns boolean language sql stable security definer set search_path='' as $$select coalesce("authorization".can_access_school(target_school) and exists(select 1 from app.classes where school_id=target_school and id=target_class and status='active'),false)$$;
revoke execute on function "authorization".active_class(uuid,uuid) from public,anon,authenticated,service_role,cuevo_worker;
grant execute on function "authorization".active_class(uuid,uuid) to cuevo_api;
drop policy courses_read on app.courses;
create policy courses_read on app.courses for select to cuevo_api using("authorization".active_class(school_id,class_id) and "authorization".has_entitlement(school_id,'learning') and "authorization".can_view_class(school_id,class_id) and (
 ("authorization".can_teach_subject(school_id,class_id,subject_id) and (created_by="authorization".actor_id() or "authorization".current_role(school_id)='admin')) or "authorization".current_role(school_id)='coordinator' or (status='PUBLISHED' and "authorization".current_role(school_id) in('student','parent'))));
create or replace function "authorization".unit_course(target_school uuid,target_unit uuid) returns uuid language sql stable security definer set search_path='' as $$select course_id from app.units where school_id=target_school and id=target_unit and "authorization".can_read_course(target_school,course_id)$$;
create or replace function "authorization".lesson_course(target_school uuid,target_lesson uuid) returns uuid language sql stable security definer set search_path='' as $$select "authorization".unit_course(school_id,unit_id) from app.lessons where school_id=target_school and id=target_lesson and "authorization".can_access_school(target_school)$$;
create or replace function "authorization".activity_course(target_school uuid,target_activity uuid) returns uuid language sql stable security definer set search_path='' as $$select "authorization".lesson_course(school_id,lesson_id) from app.activities where school_id=target_school and id=target_activity and "authorization".can_access_school(target_school)$$;
create or replace function "authorization".assessment_course(target_school uuid,target_assessment uuid) returns uuid language sql stable security definer set search_path='' as $$select course_id from app.assessments where school_id=target_school and id=target_assessment and "authorization".can_read_course(target_school,course_id) and "authorization".has_entitlement(target_school,'assessment')$$;
commit;
